refentry.refsect1:
&reftitle.changelog;
&Version; &Description;
8.4.0
SOAP_PERSISTENCE_SESSION ahora funciona cuando la extensión session está compilada como módulo compartido; anteriormente fallaba silenciosamente. SoapServer::setPersistence ahora también lanza un Error cuando se solicita SOAP_PERSISTENCE_SESSION mientras que la extensión session no está disponible.

  &reftitle.examples;



    Ejemplo SoapServer::setPersistence


<?php

class MyFirstPersistentSoapServer
{
    private $resource; // (Por ejemplo PDO, mysqli, etc..)
    public $myvar1;
    public $myvar2;

    public function __construct()
    {
        $this->resource = CodeToStartOurResourceUp(); // Se inicia nuestro recurso
    }

    public function __unserialize(array $data): void
    {
        $this->myvar1 = $data['myvar1'];
        $this->myvar2 = $data['myvar2'];

        $this->resource = CodeToStartOurResourceUp();
    }

    public function __serialize(): array
    {
        // Se asegura de excluir $resource aquí, así nuestros datos pueden persistir en sesión.
        // Si se olvida, la deserialización de los datos en la próxima petición fallará;
        // así, un objeto MyFirstPersistentSoapServer no sería persistente entre las peticiones.
        return [
            'myvar1' => $this->myvar1,
            'myvar2' => $this->myvar2,
        ];
    }
}

try {
    session_start();
    $server = new SoapServer(null, ['uri' => $_SERVER['REQUEST_URI']]);
    $server->setClass('MyFirstPersistentSoapServer');
    // setPersistence() DEBE ser llamada después de setClass(), ya que el comportamiento de setClass()
    // establece SOAP_PERSISTENCE_REQUEST.
    $server->setPersistence(SOAP_PERSISTENCE_SESSION);
    $server->handle();
} catch (SoapFault $e) {
    error_log("SOAP ERROR: " . $e->getMessage());
}
